import * as THREE from './three.module.js';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
const material=(color,roughness=.48)=>new THREE.MeshStandardMaterial({color,roughness});
function mesh(g,m,parent,x=0,y=0,z=0){const o=new THREE.Mesh(g,m);o.position.set(x,y,z);o.castShadow=true;o.receiveShadow=true;parent.add(o);return o;}
function pencil(color=0xf8c649,length=4){const g=new THREE.Group();const barrel=mesh(new THREE.CylinderGeometry(.145,.145,length,6),material(color),g);barrel.rotation.y=Math.PI/6;mesh(new THREE.ConeGeometry(.145,.6,6),material(0xd7b189),g,0,length/2+.3);mesh(new THREE.ConeGeometry(.051,.2,6),material(0x373735),g,0,length/2+.54);mesh(new THREE.CylinderGeometry(.151,.151,.32,12),material(0xb6bcb1,.25),g,0,-length/2-.16);mesh(new THREE.CylinderGeometry(.15,.15,.35,12),material(0xe58c91),g,0,-length/2-.49);return g;}
function pen(){const g=new THREE.Group();mesh(new THREE.CylinderGeometry(.16,.12,2.65,24),material(0x9b8cc9),g);mesh(new THREE.CylinderGeometry(.195,.195,1.05,24),material(0xb3a3d8),g,0,1.6);mesh(new THREE.SphereGeometry(.195,24,12),material(0xb3a3d8),g,0,2.13).scale.y=.35;mesh(new THREE.BoxGeometry(.07,.85,.10),material(0xe4dfed),g,.19,1.6,.1);mesh(new THREE.ConeGeometry(.12,.38,20),material(0xd4d5ca,.2),g,0,-1.51).rotation.z=Math.PI;return g;}
function ruler(){const g=new THREE.Group();mesh(new THREE.BoxGeometry(.82,3.8,.14),material(0xaacbd2),g);for(let i=0;i<24;i++)mesh(new THREE.BoxGeometry(i%5===0?.28:.14,.018,.008),material(0x4b777c),g,.4-(i%5===0?.14:.07),-1.65+i*.14,.078);return g;}
function eraser(){const g=new THREE.Group();mesh(new THREE.BoxGeometry(1.35,.8,.55),material(0xe88a77),g);mesh(new THREE.BoxGeometry(.76,.82,.57),material(0xf6e5cb),g,-.12);return g;}
function notebook(){const g=new THREE.Group();mesh(new THREE.BoxGeometry(1.65,2.0,.18),material(0xeeeede),g,0,0,.01);mesh(new THREE.BoxGeometry(1.8,2.15,.09),material(0x688a6b),g,0,0,.16);mesh(new THREE.BoxGeometry(1.8,2.15,.09),material(0x547653),g,0,0,-.14);mesh(new THREE.BoxGeometry(.15,2.15,.34),material(0x365b42),g,.79);mesh(new THREE.BoxGeometry(.72,.50,.015),material(0xf3ead2),g,0,.27,.21);for(let i=0;i<3;i++)mesh(new THREE.BoxGeometry(.45,.018,.016),material(0xb2b09b),g,0,.4-i*.12,.223);return g;}
function setup(canvas,span=9){const renderer=new THREE.WebGLRenderer({canvas,alpha:true,antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.setClearColor(0x000000,0);renderer.outputColorSpace=THREE.SRGBColorSpace;const scene=new THREE.Scene();const camera=new THREE.PerspectiveCamera(32,1,.1,100);camera.position.z=span;scene.add(new THREE.HemisphereLight(0xffffff,0x8a9985,3));const light=new THREE.DirectionalLight(0xfff4df,4);light.position.set(-3,5,7);scene.add(light);const fill=new THREE.DirectionalLight(0xc9dbea,1.5);fill.position.set(5,-2,3);scene.add(fill);function resize(){const w=canvas.clientWidth,h=canvas.clientHeight;renderer.setSize(w,h,false);camera.aspect=w/h;camera.updateProjectionMatrix();}new ResizeObserver(resize).observe(canvas);resize();return{renderer,scene,camera};}
let worlds=[];try{const w=setup($('#world'),13.5);worlds.push(w);const items=[];function add(o,x,y,z,rz,scale=1){o.position.set(x,y,z);o.rotation.set(.2,-.35,rz);o.scale.setScalar(scale);o.userData.base=o.position.clone();o.userData.phase=items.length*1.8;w.scene.add(o);items.push(o);}add(pencil(),.2,.45,.6,-.53,1.05);add(pen(),-1.8,.9,-.2,.56,.87);add(ruler(),1.85,-.2,-.65,-.43,.9);add(eraser(),-1.5,-1.85,.6,-.24,.85);add(notebook(),.6,-1.75,-.7,.24,.8);add(pencil(0xf1876f,2.8),1.6,2,-1,.66,.63);
const ray=new THREE.Raycaster(),pointer=new THREE.Vector2(),plane=new THREE.Plane(new THREE.Vector3(0,0,1),0),hit=new THREE.Vector3(),offset=new THREE.Vector3();let selected=null,moved=false,startX=0,startY=0;
function point(e){const r=$('#world').getBoundingClientRect();pointer.set((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1);ray.setFromCamera(pointer,w.camera);}
$('#world').addEventListener('pointerdown',e=>{point(e);const hitObj=ray.intersectObjects(items,true)[0];if(!hitObj)return;selected=hitObj.object;while(selected.parent!==w.scene)selected=selected.parent;plane.constant=-selected.position.z;ray.ray.intersectPlane(plane,hit);offset.copy(selected.position).sub(hit);$('#world').setPointerCapture(e.pointerId);startX=e.clientX;startY=e.clientY;moved=false;});
$('#world').addEventListener('pointermove',e=>{point(e);if(selected){moved ||=Math.abs(e.clientX-startX)+Math.abs(e.clientY-startY)>6;ray.ray.intersectPlane(plane,hit);selected.position.copy(hit.add(offset));selected.position.x=THREE.MathUtils.clamp(selected.position.x,-2.6,2.6);selected.position.y=THREE.MathUtils.clamp(selected.position.y,-2.4,2.5);selected.rotation.z+=(e.movementX||0)*.005;selected.userData.base.copy(selected.position);}});
function release(){if(selected&&!moved)selected.rotation.z+=.35;selected=null;}$('#world').addEventListener('pointerup',release);$('#world').addEventListener('pointercancel',release);
$('#world').tabIndex=0;$('#world').addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();const o=items[0];o.userData.base.x+=e.key==='ArrowLeft'?-.15:e.key==='ArrowRight'?.15:0;o.userData.base.y+=e.key==='ArrowUp'?.15:e.key==='ArrowDown'?-.15:0;o.userData.base.x=THREE.MathUtils.clamp(o.userData.base.x,-2.6,2.6);o.userData.base.y=THREE.MathUtils.clamp(o.userData.base.y,-2.4,2.5);}});
const lab=setup($('#pencil-view'),10.5);worlds.push(lab);const demo=new THREE.Group();demo.rotation.z=-Math.PI/2+.15;demo.rotation.y=.25;lab.scene.add(demo);const coat=mesh(new THREE.CylinderGeometry(.26,.26,4.3,6),material(0xeabc3f),demo);const wood=mesh(new THREE.CylinderGeometry(.215,.215,4.5,12),material(0xd6b385),demo);const core=mesh(new THREE.CylinderGeometry(.065,.065,4.9,16),material(0x3a3c39),demo);mesh(new THREE.ConeGeometry(.26,.7,6),material(0xd6b385),demo,0,2.5);mesh(new THREE.ConeGeometry(.065,.22,12),material(0x393b36),demo,0,2.88);
let reveal=0;function setReveal(v){reveal=v;$('#reveal').value=v;coat.position.x=-v/100*.8;wood.position.x=v/100*.25;core.position.x=v/100*.75;coat.scale.y=1-v/100*.48;wood.scale.y=1-v/100*.22;$('#lab-caption').textContent=v>35?'سه لایه، از روکش تا قلب گرافیتی':'روکش رنگی • چوب • مغزی گرافیتی';}$('#reveal').addEventListener('input',e=>setReveal(+e.target.value));$('#pencil-view').addEventListener('pointermove',e=>{const r=e.currentTarget.getBoundingClientRect();setReveal(Math.round(THREE.MathUtils.clamp((e.clientX-r.left)/r.width,0,1)*100));});$('#pencil-view').addEventListener('pointerdown',()=>setReveal(reveal<50?100:0));
let visible=true;document.addEventListener('visibilitychange',()=>visible=!document.hidden);function animate(t){requestAnimationFrame(animate);if(!visible)return;for(const o of items){if(o!==selected){o.position.y=o.userData.base.y+(reduced?0:Math.sin(t*.00075+o.userData.phase)*.11);if(!reduced)o.rotation.y=-.35+Math.sin(t*.00035+o.userData.phase)*.16;}}for(const s of worlds)s.renderer.render(s.scene,s.camera);}requestAnimationFrame(animate);
}catch(e){console.error(e);$('#scene-error').hidden=false;}
$$('[data-shop]').forEach(b=>b.addEventListener('click',()=>location.assign('shop.html')));
const board=$('#board'),ctx=board.getContext('2d');let strokes=[],active=null,tool='pencil',color='#285b47',drawing=false;
function resizeBoard(){const d=Math.min(devicePixelRatio,2);board.width=Math.round(board.clientWidth*d);board.height=Math.round(board.clientHeight*d);ctx.setTransform(d,0,0,d,0,0);render();}function draw(s){if(!s.points.length)return;ctx.save();ctx.globalCompositeOperation=s.tool==='eraser'?'destination-out':'source-over';ctx.globalAlpha=s.tool==='marker'?.58:1;ctx.strokeStyle=s.color;ctx.fillStyle=s.color;ctx.lineWidth=s.tool==='eraser'?28:s.tool==='marker'?13:s.tool==='color'?4:2;ctx.lineCap='round';ctx.lineJoin='round';ctx.beginPath();s.points.forEach((p,i)=>{const x=p[0]*board.clientWidth,y=p[1]*board.clientHeight;i?ctx.lineTo(x,y):ctx.moveTo(x,y);});if(s.points.length===1){ctx.arc(s.points[0][0]*board.clientWidth,s.points[0][1]*board.clientHeight,ctx.lineWidth/2,0,Math.PI*2);ctx.fill();}else ctx.stroke();ctx.restore();}function render(){ctx.clearRect(0,0,board.clientWidth,board.clientHeight);strokes.forEach(draw);if(active)draw(active);$('#board-placeholder').hidden=strokes.length>0||!!active;$('#undo').disabled=!strokes.length;}function pos(e){const r=board.getBoundingClientRect();return[(e.clientX-r.left)/r.width,(e.clientY-r.top)/r.height];}
board.addEventListener('pointerdown',e=>{if(e.button!==0)return;drawing=true;board.setPointerCapture(e.pointerId);active={tool,color,points:[pos(e)]};render();});board.addEventListener('pointermove',e=>{if(!drawing)return;for(const event of e.getCoalescedEvents?.()||[e])active.points.push(pos(event));render();});function finish(){if(!drawing)return;drawing=false;if(active)strokes.push(active);active=null;render();}board.addEventListener('pointerup',finish);board.addEventListener('pointercancel',finish);new ResizeObserver(resizeBoard).observe(board);
const toolNames={pencil:'مداد',color:'مداد رنگی',marker:'ماژیک',eraser:'پاک‌کن'};function chooseTool(value){if(!Object.hasOwn(toolNames,value))throw Error('Unknown tool');tool=value;$$('[data-tool]').forEach(b=>{b.classList.toggle('active',b.dataset.tool===tool);b.setAttribute('aria-pressed',b.dataset.tool===tool);});$('#tool-status').textContent=toolNames[tool]+' آماده‌ست!';}$$('[data-tool]').forEach(b=>b.addEventListener('click',()=>chooseTool(b.dataset.tool)));$$('[data-color]').forEach(b=>b.addEventListener('click',()=>{color=b.dataset.color;$$('[data-color]').forEach(c=>c.classList.toggle('selected',c===b));if(tool==='eraser')chooseTool('color');}));$('#undo').addEventListener('click',()=>{strokes.pop();render();});$('#clear').addEventListener('click',()=>{if(strokes.length&&confirm('همهٔ نقاشی پاک شود؟')){strokes=[];render();}});let toastTimer;function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3000);}$('#save').addEventListener('click',()=>{if(!strokes.length){toast('اول یک چیزی بکش!');return;}const out=document.createElement('canvas');out.width=board.width;out.height=board.height;const c=out.getContext('2d');c.fillStyle='#fffef9';c.fillRect(0,0,out.width,out.height);c.drawImage(board,0,0);const a=document.createElement('a');a.download='behjat-my-imagination.png';a.href=out.toDataURL('image/png');a.click();toast('نقاشی برای ذخیره آماده شد ♡');});
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'select_drawing_tool',title:'انتخاب ابزار نقاشی',description:'Select the active tool on the drawing board; does not draw or clear anything.',inputSchema:{type:'object',properties:{tool:{type:'string',enum:Object.keys(toolNames)}},required:['tool'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||typeof input!=='object'||Object.keys(input).some(k=>k!=='tool'))throw Error('Invalid input');chooseTool(input.tool);return{tool};}})).catch(console.warn);}catch(e){console.warn(e);}}



